#cprev{width:min(78vw,310px)!important;height:min(78vw,310px)!important;border-radius:50%!important;background:#161616!important;border:3px solid #fff!important;box-shadow:0 0 34px #fff5!important;overflow:hidden!important;position:relative;flex:none}
