#gprev{width:min(90vw,360px);aspect-ratio:1;border-radius:18px;background:#111;border:2px solid #ffffff2a;box-shadow:0 0 30px #fff3;overflow:hidden;flex:none;margin:12px 0 6px;display:flex;align-items:center;justify-content:center}
#gprev canvas{width:100%;height:100%;display:block;touch-action:none;cursor:grab}#gprev canvas:active{cursor:grabbing}
#gprev .gph{width:78%;aspect-ratio:1;border-radius:50%;border:4px solid #fff;display:flex;align-items:center;justify-content:center;font-size:110px}#gprev .gph .ico{opacity:.3}
