#gzr .zs{font-size:16px;display:flex}#gzr .zl{font-size:28px;display:flex}
#gRot{width:44px;height:44px;padding:0;font-size:24px;background:#ffffff22;flex:none;display:flex;align-items:center;justify-content:center}
.grow{display:flex;gap:10px;align-items:center;margin-top:14px}
