const $=s=>document.querySelector(s),wait=ms=>new Promise(r=>setTimeout(r,ms));
const S={ed:1,n:6,name:'',av:{g:0,hair:1,hat:0,eyes:0,cloth:1,face:0}};
let P=[];

function show(id){
  document.querySelectorAll('.scr').forEach(e=>e.classList.toggle('on',e.id==id));
  document.body.className=(id=='lobby'||id=='game'||id=='olobby')?'e'+S.ed:'';
  document.body.classList.toggle('nocur',!ST.cursor);document.body.classList.toggle('noanim',!ST.anim);document.body.classList.toggle('hasbg',!!window.HB);
  if(id=='intro')runIntro();else clearTimeout(tm);
  fabUp();
