document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>show(b.dataset.go));

/* ================= الصوت ================= */
let ac;const A=()=>ac||(ac=new (window.AudioContext||window.webkitAudioContext)());
function tone(f,t,d,type='square',v=.12,f2){
  if(!ST.sound)return;
  const a=A(),o=a.createOscillator(),g=a.createGain(),s=a.currentTime+t;
  o.type=type;o.frequency.setValueAtTime(f,s);if(f2)o.frequency.exponentialRampToValueAtTime(f2,s+d);
  o.connect(g);g.connect(a.destination);g.gain.setValueAtTime(v,s);g.gain.exponentialRampToValueAtTime(.001,s+d);o.start(s);o.stop(s+d);
}
const sfx={
  start(){tone(73,0,2.2,'sawtooth',.1);[[147,0],[147,.45],[175,.9],[196,1.35]].forEach(([f,t])=>tone(f,t,.4,'triangle',.25));tone(98,1.35,.9,'triangle',.25)},
  vote(){vb(30);tone(660,0,.12,'sine',.25);tone(880,.08,.12,'sine',.2)},
  kill(){vb([120,60,200]);tone(400,0,.6,'sawtooth',.2,40);tone(90,.1,.5,'square',.2)},
  save(){[523,659,784,1047].forEach((f,i)=>tone(f,i*.1,.3,'sine',.2))},
  reveal(){[392,466,587].forEach((f,i)=>tone(f,i*.15,.4,'triangle',.25))},
  night(){tone(110,0,1,'sine',.2);tone(82,.3,1.2,'sine',.2)}
};

/* ================= المقدمة ================= */
const SL=[
 {t:"الفكرة",l:["لعبة ورق جماعية تجمع بين الحيلة والذكاء","كل لاعب يستلم دوراً سرياً","مافيا • دكتور • شايب • مواطن"]},
 {t:"الأدوار",l:["المافيا: تقتل لاعباً كل ليلة وتتخفى نهاراً","الدكتور: يحمي لاعباً واحداً كل ليلة","الشايب: يسأل ليلاً هل فلان مافيا؟","المواطن: يحلل ويناقش ويصوّت"]},
 {t:"الليل",l:["الكل ينام ثم يستيقظ كل دور بدوره","المافيا تتفق على ضحية","إذا حماها الدكتور ينجو الجميع"]},
 {t:"النهار",l:["تُعلن نتيجة الليل","الكل يناقش ويتهم عبر الشات","ثم التصويت ضمن وقت محدد"]},
 {t:"التصويت",l:["من يحصل على أكثر الأصوات يخرج ويُكشف دوره","التعادل = لا أحد يخرج","من لم يصوّت في الوقت يُعتبر ممتنعاً"]},
 {t:"الفوز",l:["المواطنون يفوزون بإخراج كل المافيا","المافيا تفوز إذا تساوى عددها مع البقية","جاهز؟ اضغط لعب!"]}
];
let si=0,tm;
function drawSlide(dir){
  const el=$('#rb'),s=SL[si];
  el.className='';void el.offsetWidth;if(dir)el.className=dir;
  el.innerHTML=`<div class="rh glow"><small>${Tr('القوانين')} • ${si+1} / ${SL.length}</small>${Tr(s.t)}</div>`+s.l.map((x,i)=>`<div class="rl" style="animation-delay:${.15+i*.15}s">${Tr(x)}</div>`).join('');
  $('#dots').innerHTML=SL.map((_,i)=>`<i class="${i==si?'on':''}"></i>`).join('');
  $('#nx').disabled=si==SL.length-1;$('#pv').disabled=si==0;
}
function go(d){const n=si+d;if(n<0||n>=SL.length)return;si=n;drawSlide(d>0?'nx':'pv')}
function runIntro(){si=0;drawSlide()}
$('#nx').onclick=()=>go(1);$('#pv').onclick=()=>go(-1);
addEventListener('keydown',e=>{if($('#intro').classList.contains('on')){if(e.key=='ArrowLeft')go(1);if(e.key=='ArrowRight')go(-1)}});
let tx=null;$('#rb').addEventListener('touchstart',e=>tx=e.touches[0].clientX,{passive:true});
$('#rb').addEventListener('touchend',e=>{if(tx==null)return;const d=e.changedTouches[0].clientX-tx;tx=null;if(Math.abs(d)>45)go(d<0?1:-1)});
$('#cl').src=CARDS['1-mafia'];$('#cr').src=CARDS['1-elder'];$('#cm').src=CARDS['2-mafia'];
$('#bPlay').onclick=()=>{A().resume&&A().resume();show('modes')};
$('#bRules').onclick=()=>ov(`<div style="max-width:340px;text-align:center;line-height:1.8">${SL.map((s,i)=>`<div class="glow" style="font-size:24px;margin-top:12px">${i+1}. ${Tr(s.t)}</div>`+s.l.map(x=>`<div style="font-size:17px;opacity:.9">${Tr(x)}</div>`).join('')).join('')}</div>`,'إغلاق');
/* مؤشر القلو */
(()=>{const c=$('#cur');let x=-99,y=-99,cx=x,cy=y,hide;
 addEventListener('pointermove',e=>{x=e.clientX;y=e.clientY;c.classList.add('on');c.classList.toggle('h',!!e.target.closest('button'));clearTimeout(hide);if(e.pointerType!='mouse')hide=setTimeout(()=>c.classList.remove('on'),700)});
 addEventListener('pointerdown',e=>{x=cx=e.clientX;y=cy=e.clientY;c.classList.add('on')});
 document.addEventListener('mouseleave',()=>c.classList.remove('on'));
 (function f(){cx+=(x-cx)*.28;cy+=(y-cy)*.28;c.style.transform=`translate(${cx}px,${cy}px)`;requestAnimationFrame(f)})()})();

/* ================= الإصدارات ================= */

/* ================= تخصيص الشخصية ================= */
const BGS={1:'data:image/svg+xml;base64,',2:'data:image/svg+xml;base64,',3:'data:image/svg+xml;base64,'};
const rnd=n=>Math.floor(Math.random()*n);
const SK=['#f0c8a4','#e3b08a','#c98e62','#a8683f','#7d4a2b','#52301c'];
const HC=['#1b1b1d','#3a2616','#7a4a22','#c9a227','#a8321a','#8f8f95','#e9e6df','#3b6ea5'];
const COL=['#f4f4ef','#e3d5b4','#9097a0','#1b1b21','#1f2d58','#2f7bd6','#2e8b57','#7a4b2a','#7d1f3a','#c0392b'];
const CN=['أبيض','كريمي','رمادي','أسود','كحلي','أزرق','أخضر','بني','عنابي','أحمر'];
const mix=(h,t,p)=>{const n=parseInt(h.slice(1),16);return '#'+[n>>16,n>>8&255,n&255].map(v=>Math.round(v+(t-v)*p).toString(16).padStart(2,'0')).join('')};
let UID=0;
const r1=n=>Math.round(n*10)/10;
/* خصلة شعر مدبّبة الطرفين */
const lk=(x1,y1,cx,cy,x2,y2,w)=>{const dx=x2-x1,dy=y2-y1,l=Math.hypot(dx,dy)||1,nx=-dy/l,ny=dx/l;return`M${r1(x1)} ${r1(y1)}Q${r1(cx+nx*w)} ${r1(cy+ny*w)} ${r1(x2)} ${r1(y2)}Q${r1(cx-nx*w*.35)} ${r1(cy-ny*w*.35)} ${r1(x1)} ${r1(y1)}Z`};
/* مجموعة خصل تنساب من خط جذور إلى خط أطراف */
const flow=(a,b,c,d,n,cv,w,j=0)=>{let s='';for(let i=0;i<n;i++){const t=n>1?i/(n-1):.5,q=(i*37%11)/11-.5,x1=a[0]+(b[0]-a[0])*t,y1=a[1]+(b[1]-a[1])*t,x2=c[0]+(d[0]-c[0])*t+q*j,y2=c[1]+(d[1]-c[1])*t+q*j*.6,mx=(x1+x2)/2,my=(y1+y2)/2,dx=x2-x1,dy=y2-y1,l=Math.hypot(dx,dy)||1;s+=lk(x1,y1,mx-dy/l*cv,my+dx/l*cv,x2,y2,w*(.75+((i*13)%7)/14))}return s};
const HEAD='M100 46C124 46 138 62 138 88C138 112 135 128 127 142C120 153 111 159 100 159C89 159 80 153 73 142C65 128 62 112 62 88C62 62 76 46 100 46Z';
const JAW='M63 94C63 114 66 128 73 142C80 153 89 159 100 159C111 159 120 153 127 142C134 128 137 114 137 94';
const TM='M-4 262L0 230C4 204 38 192 76 184L124 184C162 192 196 204 200 230L204 262Z';
const TF='M40 262L40 244C42 224 62 206 86 196L114 196C138 206 158 224 160 244L160 262Z';
/* ============ الشعر ============ */
/* [اسم, خلفية, هيئة, ضوء, ظل, ينزل, موجات كبيرة] */
const SW=(top,w=1)=>top;
const HM=[
 ['أصلع'],
 ['قصير','','M60 104C54 78 58 52 76 42C88 34 112 32 126 38C142 46 148 74 140 104C139 90 137 80 131 73C123 66 112 63 100 64C88 63 77 66 69 73C63 80 61 90 60 104Z',
  flow([68,62],[132,60],[74,46],[136,50],9,-3,2.2,2),flow([84,62],[118,62],[96,44],[112,44],5,3,2.2,2),'',
  flow([64,70],[132,66],[72,46],[138,52],4,-5,6,2)],
 ['كثيف مرفوع','','M60 106C50 86 48 62 56 46C62 26 88 8 120 10C146 12 160 28 152 48C158 68 148 90 141 106C140 92 138 82 133 74C126 66 116 64 106 64C94 64 82 66 74 74C66 82 62 92 60 106Z',
