  document.querySelectorAll('#rows button').forEach(b=>b.onclick=()=>{const k=b.dataset.k,n=CNT(k,S.av.g);S.av[k]=(S.av[k]+ +b.dataset.d+n)%n;paint()});
  paint();
}
function paint(){
  const g=S.av.g;CATS.forEach(([k])=>{S.av[k]=((S.av[k]|0)%CNT(k,g)+CNT(k,g))%CNT(k,g)});if(g)S.av.beard=0;
  $('#cprev').innerHTML=avatar(Object.assign({},S.av,{img:''}));$('#row_beard').style.display=g?'none':'';
  CATS.forEach(([k])=>{const L=CNAMES(k,g);$('#v_'+k).textContent=L?Tr(L[S.av[k]]):(S.av[k]+1)+'/'+CNT(k,g)});
  $('#gB').classList.toggle('on',!g);$('#gG').classList.toggle('on',!!g);
}
