let GSRC=null,GZ=1,GX=0,GY=0,GR=0;const GW=360,GD=280;
const gDims=()=>GR%180?[GSRC.height,GSRC.width]:[GSRC.width,GSRC.height];
const gBase=()=>{const[w,h]=gDims();return Math.min(GW/w,GW/h)};
function gAuto(){if(!GSRC)return;const[w,h]=gDims();GZ=Math.max(.3,Math.min(5,GD/Math.min(w,h)/gBase()));GX=GY=0}
function clampG(){GX=Math.max(-GW/2,Math.min(GW/2,GX));GY=Math.max(-GW/2,Math.min(GW/2,GY))}
function gDraw(x,cx,cy,k){x.save();x.imageSmoothingQuality='high';x.translate(cx+GX*k,cy+GY*k);x.rotate(GR*Math.PI/180);const s=gBase()*GZ*k;x.scale(s,s);x.drawImage(GSRC,-GSRC.width/2,-GSRC.height/2);x.restore()}
function paintGal(){const has=!!GSRC;$('#gc').style.display=has?'block':'none';$('#gph').style.display=has?'none':'flex';$('#gzr').style.display=has?'flex':'none';$('#gHint').style.display=has?'':'none';$('#gOk').disabled=!has;$('#gReset').style.display=has?'':'none';
