function applyBg(){const id=ST.bg+'',u=id=='c'?(localStorage.fsBgC||''):(BGS[id]||'');$('#bgl').style.backgroundImage=u?`url(${u})`:'none';window.HB=!!u;document.body.classList.toggle('hasbg',!!u)}
function readBg(f){return new Promise(res=>{const r=new FileReader();r.onload=()=>{const i=new Image();i.onload=()=>{const k=Math.min(1,1280/Math.max(i.width,i.height)),c=document.createElement('canvas');c.width=i.width*k;c.height=i.height*k;c.getContext('2d').drawImage(i,0,0,c.width,c.height);res(c.toDataURL('image/jpeg',.78))};i.onerror=()=>res(null);i.src=r.result};r.onerror=()=>res(null);r.readAsDataURL(f)})}

/* ================= الإصدارات ================= */
function buildEds(){
  const E=[[1,'الإصدار الأول','بطاقات سوداء فاخرة بتوهج أبيض',`<img src="${CARDS['1-mafia']}"><img src="${CARDS['1-doctor']}">`],
   [2,'الإصدار الثاني','بطاقات ورق قديم بطابع كلاسيكي',`<img src="${CARDS['2-mafia']}"><img src="${CARDS['2-doctor']}">`]];
  $('#edList').innerHTML=E.map(([n,t,d,f],i)=>`<button class="ed2 v${n}" data-ed="${n}" style="animation-delay:${i*.15}s"><div class="fan">${f}</div><div><b>${t}</b><small>${d}</small></div></button>`).join('');
}
buildEds();
$('#edList').onclick=e=>{const b=e.target.closest('[data-ed]');if(!b)return;S.ed=+b.dataset.ed;afterEd()};

/* ================= الغرفة ================= */
const NAMES=['سلطان','نورة','فهد','ريم','خالد','منى','ماجد','هند','بدر','لولو','تركي'];
const code=Math.random().toString(36).slice(2,6).toUpperCase();
let joinT=0;
function openLobby(){show('lobby');if(!$('#nameIn').value)$('#nameIn').value=CH.name||'';fill()}
function fill(){
  $('#nV').textContent=S.n;
  const id=++joinT,list=$('#plist');list.innerHTML='';
  const add=(txt,av,me)=>{const d=document.createElement('div');d.className='t join'+(me?' me':'');
    d.innerHTML=avatar(av)+`<b>${txt}</b>`;list.appendChild(d)};
  add($('#nameIn').value||'أنت',S.av,1);
  (async()=>{for(let i=0;i<S.n-1;i++){await wait(550);if(id!=joinT)return;sfx.vote();add(NAMES[i],rndAv())}})();
}
$('#nM').onclick=()=>{S.n=Math.max(5,S.n-1);fill()};
$('#nP').onclick=()=>{S.n=Math.min(12,S.n+1);fill()};
$('#nameIn').oninput=()=>{const f=$('#plist .t b');if(f)f.textContent=$('#nameIn').value||'أنت'};
$('#share').onclick=async()=>{
  const url=location.href.split('?')[0]+'?room='+code;
  try{if(navigator.share)await navigator.share({title:'لعبة المافيا',url});else{await navigator.clipboard.writeText(url);$('#share').textContent='✔ تم نسخ الرابط'}}catch(e){}
};

