  };
 o.oninput=e=>{const k=e.target.dataset.r;if(k){ST[k]=+e.target.value;applyST()}};
 o.onchange=async e=>{if(e.target.id!='bgf'||!e.target.files[0])return;const u=await readBg(e.target.files[0]);if(!u)return dlg('تعذر قراءة الصورة');
  try{localStorage.fsBgC=u}catch(x){return dlg('الصورة كبيرة جداً، جرّب صورة أصغر')}
  ST.bg='c';applyST();o.classList.remove('on');openSet()};
 return p.then(()=>{applyST();api('save',{settings:ST})})}
$('#bSet').onclick=openSet;$('#bStats').onclick=myStats;
function fabUp(){setTimeout(()=>{const o=document.querySelector('.scr.on');if(o&&o.id=='modes')myLine()},0);const on=document.querySelector('.scr.on'),id=on&&on.id,v=(id=='game'&&MODE=='solo'&&!OL)||(OL&&(id=='game'||id=='olobby'));$('#bChat').style.display=v?'':'none';if(!v)$('#chat').classList.remove('on')}

/* ================= إحصائيات اللاعب ================= */
const lsGet=()=>{try{return JSON.parse(localStorage.fsLS||'{}')}catch(e){return{}}};
function recLocal(mode,role,won){const d=lsGet();d.g=(d.g||0)+1;if(won!==null){const k=won?'w':'l';d[k]=(d[k]||0)+1}
 const m=d.m=d.m||{};m[mode]=m[mode]||{g:0,w:0};m[mode].g++;if(won)m[mode].w++;
 if(role){const r=d.r=d.r||{};r[role]=r[role]||{g:0,w:0};r[role].g++;if(won)r[role].w++}
 try{localStorage.fsLS=JSON.stringify(d)}catch(e){}}
async function statData(){if(!window.FS_OFF){const r=await api('stats');if(r&&!r.err)return r}const l=lsGet();return{g:l.g||0,w:l.w||0,l:l.l||0,m:l.m||{},r:l.r||{}}}
const pct=d=>(d.w+d.l)?Math.round(d.w/(d.w+d.l)*100):0;
async function myLine(){const d=await statData(),e=$('#myLine');if(e)e.textContent=d.g?`${d.g} ${Tr('ألعاب')} • ${d.w} ${Tr('فوز')} • ${pct(d)}%`:''}
async function myStats(){const d=await statData(),nm={solo:'لعب فردي',local:'جهاز واحد',online:'أونلاين'},row=(l,o)=>`<div class="sr"><span>${l}</span><span>${o.g} • ${Tr('فوز')} ${o.w}</span></div>`;
 await ov(`<div class="dlg set"><h3>${ic('chart')} ${Tr('إحصائياتي')}</h3><div class="stg"><div><b>${d.g}</b>${Tr('ألعاب')}</div><div><b>${d.w}</b>${Tr('فوز')}</div><div><b>${d.l}</b>${Tr('خسارة')}</div><div><b>${pct(d)}%</b>${Tr('نسبة الفوز')}</div></div>
 ${Object.keys(d.m).length?`<h4>${Tr('حسب النظام')}</h4>`+Object.entries(d.m).map(([k,o])=>row(Tr(nm[k]||k),o)).join(''):''}
 ${Object.keys(d.r).length?`<h4>${Tr('حسب الدور')}</h4>`+Object.entries(d.r).map(([k,o])=>row(Tr(R[k]?R[k].n:k),o)).join(''):''}
 ${d.g?'':`<div class="dim">${Tr('ما لعبت أي لعبة بعد')}</div>`}</div>`,'تم')}

/* ================= الدردشة ================= */
let cAfter=0;
function chatAdd(n,m,me,mf){const d=document.createElement('div');d.className='cm'+(me?' me':'');d.innerHTML=`<b>${esc(n)}</b> ${mf?`<i>${ic('mafia')}</i> `:''}${esc(m)}`;const l=$('#cl2');l.appendChild(d);l.scrollTop=l.scrollHeight}
function chatClear(){$('#cl2').innerHTML='';cAfter=0}
$('#bChat').onclick=()=>$('#chat').classList.toggle('on');
async function sendChat(){const v=$('#ci').value.trim();if(!v)return;$('#ci').value='';
 if(OL){await api('chat',{code:OL.code,msg:v});poll()}else if(MODE=='solo')soloSay(v)}
$('#cs').onclick=sendChat;$('#ci').onkeydown=e=>{if(e.key=='Enter')sendChat()};

/* ================= اللعبة (فردي / جهاز واحد) ================= */
const R={mafia:{n:'مافيا',i:'mafia',d:'اقتل أكبر عدد دون أن يعرفوك'},doctor:{n:'دكتور',i:'doctor',d:'مهمتك معالجة المواطنين'},elder:{n:'شايب',i:'elder',d:'اسأل: هل فلان مافيا؟'},citizen:{n:'مواطن',i:'user',d:'ساعد في كشف المافيا'}};
const shuffle=a=>{for(let i=a.length-1;i>0;i--){const j=rnd(i+1);[a[i],a[j]]=[a[j],a[i]]}return a};
const mkRoles=n=>shuffle(['mafia','mafia','doctor','elder',...Array(n-4).fill('citizen')]);
let MODE='solo',OL=null,THR={},SUSP={},CHK={};
function card(r,ed=S.ed){const o=R[r];if(ed<3)return `<img class="cimg" src="${CARDS[ed+'-'+r]}" alt="${Tr(o.n)}">`;return `<div class="card c1"><div class="ic">${ic(o.i)}</div><div class="nm k-${r}">${Tr(o.n)}</div><div class="ds">${Tr(o.d)}</div></div>`}
function ov(html,btn){return new Promise(res=>{const o=$('#ov');o.onclick=null;o.oninput=null;o.innerHTML=html+(btn?`<button class="big">${Tr(btn)}</button>`:'');o.classList.add('on');
  const b=o.querySelector('button.big');if(b)b.onclick=()=>{o.classList.remove('on');res()};else setTimeout(()=>{o.classList.remove('on');res()},2200)})}
function draw(){$('#grid').innerHTML=P.map(p=>`<div class="t ${p.dead?'dead':''} ${p.me?'me':''}" data-i="${p.i}" id="t${p.i}">${avatar(p.av)}<b>${esc(p.name)}</b><i class="cnt"></i></div>`).join('')}
function say(t){$('#msg').innerHTML=t}
function pick(txt,ok,sec){say(txt);return new Promise(res=>{const ts=[...document.querySelectorAll('#grid .t')],tm=$('#tm');let done=0,iv;
  const fin=p=>{if(done)return;done=1;clearInterval(iv);tm.style.display='none';ts.forEach(x=>{x.classList.remove('sel');x.onclick=null});res(p)};
  ts.forEach(el=>{const p=P[+el.dataset.i];if(ok(p)){el.classList.add('sel');el.onclick=()=>fin(p)}});
  if(sec){let s=sec;tm.style.display='block';const up=()=>{tm.innerHTML=ic('clock')+' '+s+`<i style="width:${s/sec*100}%"></i>`};up();iv=setInterval(()=>{s--;up();if(s<=0)fin(null)},1000)}})}
const alive=()=>P.filter(p=>!p.dead);
function winner(){const a=alive(),m=a.filter(p=>p.r=='mafia').length;return !m?'citizens':m>=a.length-m?'mafia':null}
const isH=p=>MODE=='local'||p.me;
const handoff=p=>{if(MODE!='local')return 0;say('');return ov(`<div class="dlg"><div class="ico-l">${ic('device')}</div>${Tr('سلّم الجهاز إلى')}<br><b>${esc(p.name)}</b></div>`,'جاهز')};
/* ذكاء اصطناعي */
const best=(l,f)=>l.map(p=>[p,f(p)]).sort((a,b)=>b[1]-a[1])[0][0];
const aiMafia=()=>best(alive().filter(p=>p.r!='mafia'),p=>(THR[p.i]||0)+Math.random()*2+(p.r=='doctor'?.3:0));
const aiDoctor=()=>{const d=P.find(p=>p.r=='doctor'&&!p.dead);return d&&Math.random()<.35?d:best(alive(),()=>Math.random())};
function aiElder(){const e=P.find(p=>p.r=='elder'&&!p.dead);const c=alive().filter(p=>p!==e&&CHK[p.i]===undefined);if(c.length){const q=c[rnd(c.length)];CHK[q.i]=q.r=='mafia'}}
function aiVote(v,votes){const c=alive().filter(p=>p!==v&&!(v.r=='mafia'&&p.r=='mafia'));
 if(v.r=='mafia'){const lead=Object.keys(votes).map(k=>P[+k]).filter(p=>!p.dead&&p.r!='mafia').sort((a,b)=>votes[b.i]-votes[a.i])[0];if(lead&&Math.random()<.6)return lead;return best(c,p=>(THR[p.i]||0)+Math.random()*2)}
 return best(c,p=>(SUSP[p.i]||0)+(v.r=='elder'?(CHK[p.i]===true?100:CHK[p.i]===false?-100:0):0)+Math.random()*2)}
function learn(out,vf){Object.entries(vf).forEach(([v,t])=>{const hit=out&&+t==out.i;if(hit&&out.r=='mafia'){SUSP[v]=(SUSP[v]||0)-2;THR[v]=(THR[v]||0)+2}else if(hit)SUSP[v]=(SUSP[v]||0)+1.5;else if(out&&out.r=='mafia')SUSP[v]=(SUSP[v]||0)+1})}
const BL=['أشك في {n}','{n} يتصرف بغرابة','أنا بريء، لا تصوتوا علي!','خلونا نصوت على {n}','أنا مع {n}، شكله مافيا','مين عنده دليل؟'];
const topSus=()=>best(alive().filter(p=>!p.me),p=>(SUSP[p.i]||0)+Math.random());
function botTalk(){shuffle(alive().filter(p=>!p.me)).slice(0,3).forEach((b,i)=>setTimeout(()=>{if(MODE!='solo'||b.dead)return;chatAdd(b.name,Tr(BL[rnd(BL.length)]).replace('{n}',topSus().name))},1500+i*2800))}
function soloSay(v){const me=P.find(p=>p.me);chatAdd(me.name,v,1);const hit=alive().find(p=>!p.me&&v.includes(p.name));
 if(hit){SUSP[hit.i]=(SUSP[hit.i]||0)+1;setTimeout(()=>chatAdd(hit.name,Tr('بريء والله يا {n}!').replace('{n}',me.name)),1100)}
 else if(Math.random()<.5){const b=best(alive().filter(p=>!p.me),()=>Math.random());setTimeout(()=>chatAdd(b.name,Tr(BL[rnd(BL.length)]).replace('{n}',topSus().name)),1200)}}
async function playGame(){
  show('game');draw();chatClear();THR={};SUSP={};CHK={};const me=P.find(p=>p.me);
  say(Tr('توزيع الكروت عشوائياً...'));await wait(1200);sfx.start();
  for(const h of P.filter(isH)){await handoff(h);await ov(card(h.r),'فهمت')}
  let round=0,w=null;
  while(!w){
    round++;$('#rd').textContent=Tr('الجولة')+' '+round;draw();say(ic('moon')+' '+Tr('حلّ الليل... الكل ينام'));sfx.night();await wait(1800);
    const A_=alive();let target=null,protect=null;
    const mh=A_.find(p=>p.r=='mafia'&&isH(p));
    if(mh){await handoff(mh);target=await pick(ic('mafia')+' '+Tr('اختر ضحية الليلة'),p=>!p.dead&&p.r!='mafia',ST.nt)}
    else{say(ic('mafia')+' '+Tr('المافيا تختار ضحية...'));await wait(1800);target=aiMafia()}
    if(!target)target=best(A_.filter(p=>p.r!='mafia'),()=>Math.random());
    draw();
    const dh=A_.find(p=>p.r=='doctor'&&isH(p));
    if(dh){await handoff(dh);protect=await pick(ic('doctor')+' '+Tr('اختر من تحميه'),p=>!p.dead,ST.nt)}
    else if(A_.some(p=>p.r=='doctor')){say(ic('doctor')+' '+Tr('الدكتور يختار من يحميه...'));await wait(1500);protect=aiDoctor()}
    draw();
    const eh=A_.find(p=>p.r=='elder'&&isH(p));
    if(eh){await handoff(eh);const q=await pick(ic('elder')+' '+Tr('اسأل: من تشك أنه مافيا؟'),p=>!p.dead&&p!==eh,ST.nt);
      if(q){sfx.reveal();await ov(`<div class="card c1"><div class="ic">${ic(q.r=='mafia'?'warn':'check')}</div><div class="nm" style="font-size:34px">${esc(q.name)}<br>${Tr(q.r=='mafia'?'مافيا!':'ليس مافيا')}</div></div>`,'تمام')}}
    else if(A_.some(p=>p.r=='elder')){say(ic('elder')+' '+Tr('الشايب يسأل عن المافيا...'));await wait(1500);aiElder()}
    draw();say(ic('sun')+' '+Tr('طلع الصباح...'));await wait(1500);
    if(target!==protect){sfx.kill();$('#t'+target.i).classList.add('kill');await wait(900);target.dead=true;draw();say(ic('knife')+' '+Tr('المافيا قتلت {n}!').replace('{n}',esc(target.name)));await wait(2200)}
    else{sfx.save();say(ic('doctor')+' '+Tr('الدكتور أنقذ الضحية! لم يمت أحد الليلة'));await wait(2200)}
    if(w=winner())break;
    draw();const voters=alive(),votes={},vf={};
    if(MODE=='solo')botTalk();
    for(const v of voters){
      let tg;
      if(isH(v)){await handoff(v);tg=await pick(ic('vote')+' '+Tr('صوّت على من تشك فيه'),p=>!p.dead&&p!==v,ST.vt)}else tg=aiVote(v,votes);
      if(!tg){say(Tr('{n} امتنع عن التصويت').replace('{n}',esc(v.name)));await wait(700);continue}
      say(ic('vote')+' '+Tr('{n} صوّت!').replace('{n}',esc(v.name)));sfx.vote();votes[tg.i]=(votes[tg.i]||0)+1;vf[v.i]=tg.i;
      const c=$('#t'+tg.i+' .cnt');c.textContent=votes[tg.i];c.classList.remove('on');void c.offsetWidth;c.classList.add('on');await wait(700)}
    await wait(500);let out=null;const vs=Object.values(votes);
    if(!vs.length||Object.keys(votes).filter(k=>votes[k]==Math.max(...vs)).length>1){say(ic('scale')+' '+Tr('تعادل في الأصوات! لم يخرج أحد'));await wait(2200)}
    else{out=P[+Object.keys(votes).find(k=>votes[k]==Math.max(...vs))];$('#t'+out.i).classList.add('out');sfx.kill();await wait(800);
      sfx.reveal();await ov(out.r=='mafia'?`<h2>${Tr('{n} كان…').replace('{n}',esc(out.name))}</h2>`+card(out.r):`<div style="width:110px">${avatar(out.av)}</div><h2>${esc(out.name)}</h2><div style="font-size:22px">${Tr('خرج من اللعبة')}</div>`,'التالي');out.dead=true;draw()}
    learn(out,vf);w=winner()}
  sfx.start();{const won=me?(me.r=='mafia')==(w=='mafia'):false;recLocal(MODE,me?me.r:'',MODE=='local'?null:won);api('game_end',{mode:MODE,n:P.length,winner:w,rounds:round,role:me?me.r:'',won})}
  await ov(`<h1 style="font-size:36px;text-align:center">${ic(w=='mafia'?'mafia':'trophy')} ${Tr(w=='mafia'?'فازت المافيا!':'فاز المواطنون!')}</h1><div style="font-size:19px;text-align:center;line-height:1.9">${P.map(p=>`${esc(p.name)}: ${ic(R[p.r].i)} ${Tr(R[p.r].n)}`).join('<br>')}</div>`,'العب مرة أخرى');
  show('modes')}
$('#startBtn').onclick=()=>{A().resume&&A().resume();MODE='solo';const nm=$('#nameIn').value.trim()||Tr('أنت'),names=shuffle([...NAMES]);
  P=mkRoles(S.n).map((r,i)=>({i,r,me:i==0,name:i==0?nm:names[i],av:i==0?S.av:rndAv(),dead:false}));playGame()};
/* جهاز واحد */
let LN=[];
function lDraw(){$('#lList').innerHTML=LN.map((n,i)=>`<div class="chip">${ic('user')} ${esc(n)}<button data-d="${i}">${ic('x')}</button></div>`).join('')||`<div class="dim">${Tr('أضف اللاعبين (5 على الأقل)')}</div>`}
function openLocal(){MODE='local';show('lsetup');lDraw()}
function lAdd(){const v=$('#lIn').value.trim();if(!v)return dlg('أكتب اسماً أولاً');if(LN.length>=12)return;LN.push(v);$('#lIn').value='';lDraw();$('#lIn').focus()}
$('#lAdd').onclick=lAdd;$('#lIn').onkeydown=e=>{if(e.key=='Enter')lAdd()};
$('#lList').onclick=e=>{const b=e.target.closest('[data-d]');if(b){LN.splice(+b.dataset.d,1);lDraw()}};
$('#lGo').onclick=()=>{if(LN.length<5)return dlg('أضف 5 لاعبين على الأقل');A().resume&&A().resume();MODE='local';P=mkRoles(LN.length).map((r,i)=>({i,r,name:LN[i],av:rndAv(),dead:false}));playGame()};
function afterEd(){MODE=='local'?openLocal():openLobby()}
$('#mList').onclick=e=>{const b=e.target.closest('[data-m]');if(!b)return;A().resume&&A().resume();MODE=b.dataset.m;if(MODE=='online')openOnl();else show('editions')};

/* ================= أونلاين ================= */
let pTm=0;
async function openOnl(code){const r=await api('hello');if(r.err||!r.uid){return dlg(r.m||'تعذر الاتصال بالخادم')}
 UK=r.uid;localStorage.fsU=UK;show('onl');if(!$('#oName').value)$('#oName').value=CH.name||r.name||'';if(code)$('#oCode').value=code}
const oNm=()=>{const v=$('#oName').value.trim();if(!v)dlg('أدخل اسمك أولاً');return v};
$('#oNew').onclick=async()=>{const name=oNm();if(!name)return;const r=await api('room_create',{name,av:S.av,night:ST.nt,vote:ST.vt});if(r.err)return dlg(r.m);enterRoom(r.code)};
$('#oJoin').onclick=async()=>{const name=oNm();if(!name)return;const code=$('#oCode').value.trim().toUpperCase();if(!code)return dlg('أدخل كود الغرفة');const r=await api('room_join',{name,code,av:S.av});if(r.err)return dlg(r.m);enterRoom(r.code)};
function enterRoom(code){OL={code,seq:null,sg:'',rv:0,fin:0,busy:0,hold:0,end:0};MODE='online';localStorage.fsR=code;chatClear();history.replaceState(null,'',location.pathname+'?room='+code);poll()}
async function poll(){clearTimeout(pTm);if(!OL||OL.busy)return;OL.busy=1;const r=await api('room_state',{code:OL.code,after:cAfter});if(!OL)return;OL.busy=0;
 if(r.err){const m=r.m;leaveOl(1);dlg(m||'الغرفة غير موجودة');return}
 await renderOl(r);if(OL)pTm=setTimeout(poll,r.room.status=='end'?2000:1500)}
function leaveOl(silent){clearTimeout(pTm);const c=OL&&OL.code,st=OL&&OL.s&&OL.s.room.status;OL=null;localStorage.removeItem('fsR');history.replaceState(null,'',location.pathname);if(c&&(st=='lobby'||st=='end')&&!silent)api('leave',{code:c});MODE='solo';show('modes')}
$('#oLeave').onclick=()=>leaveOl();
const shareUrl=()=>location.origin+location.pathname+'?room='+OL.code;
$('#oShare').onclick=async()=>{const url=shareUrl();try{if(navigator.share){await navigator.share({title:Tr('لعبة المافيا'),url});return}await navigator.clipboard.writeText(url)}catch(e){}dlg(Tr('تم نسخ الرابط')+`<br><small>${url}</small>`)};
$('#oHost').onclick=async e=>{const b=e.target.closest('button');if(!b||!OL||!OL.s)return;const d=b.dataset,c=OL.s.room.cfg;
 if(d.ed)await api('room_cfg',{code:OL.code,ed:+d.ed});else if(d.k){const n={...c};n[d.k]=+c[d.k]+ +d.d;await api('room_cfg',{code:OL.code,cfg:n})}poll()};
$('#oStart').onclick=async()=>{A().resume&&A().resume();const r=await api(OL.s&&OL.s.room.status=='end'?'room_again':'room_start',{code:OL.code});if(r.err)dlg(r.m);else poll()};
function tmUp(){const tm=$('#tm');if(!OL||!OL.end||OL.s.room.status!='play'){return}const s=Math.max(0,Math.ceil((OL.end-Date.now())/1000));tm.style.display='block';tm.innerHTML=ic('clock')+' '+s+`<i style="width:${Math.min(100,s/OL.tot*100)}%"></i>`}
setInterval(()=>{if(OL&&OL.s)tmUp()},500);
function lobbyUI(r){const R_=r.room,c=R_.cfg,sg=JSON.stringify([r.players,R_.ed,c,r.host,R_.status]);$('#oc').textContent=R_.code;
 if(sg==OL.lg)return;OL.lg=sg;
 $('#oPl').innerHTML=r.players.map(p=>`<div class="t ${p.id==r.me.id?'me':''}">${p.av?avatar(p.av):''}<b>${esc(p.name)}</b>${p.host?`<i class="mk" style="color:#ffd400">${ic('crown')}</i>`:''}</div>`).join('');
 $('#oHost').innerHTML=R_.status=='end'?`<div class="dim">${ic(R_.winner=='mafia'?'mafia':'trophy')} ${Tr(R_.winner=='mafia'?'فازت المافيا!':'فاز المواطنون!')}<br>${Tr(r.host?'اضغط لإعادة الجميع إلى الغرفة':'بانتظار المضيف ليعيد اللعبة...')}</div>`:r.host?`<div class="seg">${[1,2].map(n=>`<button data-ed="${n}" class="${R_.ed==n?'on':''}">${Tr(['الإصدار الأول','الإصدار الثاني'][n-1])}</button>`).join('')}</div>`+[['max','أقصى عدد اللاعبين',5],['night','مدة الليل (ثانية)',5],['vote','مدة التصويت (ثانية)',5]].map(([k,l,s])=>`<div class="stp2">${Tr(l)}<button data-k="${k}" data-d="${k=='max'?-1:-s}">−</button><b>${c[k]}</b><button data-k="${k}" data-d="${k=='max'?1:s}">+</button></div>`).join(''):`<div class="dim">${Tr('بانتظار المضيف ليبدأ اللعبة...')}</div>`;
 const en=R_.status=='end',ok5=en||r.players.length>=5;$('#oStart').style.display=r.host?'':'none';$('#oStart').textContent=Tr(en?'العب من جديد':'ابدأ');$('#oStart').disabled=!ok5;$('#oStart').style.opacity=ok5?1:.4;applyST()}
async function renderOl(r){const R_=r.room,me=r.me;OL.s=r;S.ed=R_.ed;
 r.chat.forEach(c=>{chatAdd(c.name,c.msg,c.name==(r.players.find(p=>p.id==me.id)||{}).name,c.ch=='m');cAfter=Math.max(cAfter,+c.id)});
 const cur=document.querySelector('.scr.on');
 if(R_.status=='end'&&OL.fin){if(!cur||cur.id!='olobby'){show('olobby');fabUp()}lobbyUI(r);return}
 if(R_.status=='lobby'){if(OL.fin||OL.rv||OL.seq!==null){OL.rv=0;OL.fin=0;OL.seq=null;OL.sg='';OL.lg='';OL.hold=0}if(!cur||cur.id!='olobby'){show('olobby');fabUp()}lobbyUI(r);return}
 if(!cur||cur.id!='game'){show('game');fabUp();OL.sg=''}
 if(!OL.rv&&me.role){OL.rv=1;sfx.start();await ov(card(me.role,R_.ed),'فهمت')}
 if(OL.seq!==R_.seq){const first=OL.seq===null;OL.seq=R_.seq;if(!first&&R_.ev)await showEv(r)}
 $('#rd').textContent=Tr('الجولة')+' '+R_.round;OL.end=Date.now()+R_.left*1000;OL.tot=R_.cfg[R_.phase=='day'?'vote':'night']||30;tmUp();
 const night=R_.phase=='night',play=R_.status=='play';let ok=()=>false,txt='';
 if(play){
  if(!me.alive)txt=Tr('أنت خارج اللعبة... تشاهد فقط');
  else if(night){
   if(me.act==null&&me.role=='mafia'){txt=ic('mafia')+' '+Tr('اختر ضحية الليلة');ok=p=>p.alive&&p.id!=me.id&&!me.mates.includes(p.id)}
   else if(me.act==null&&me.role=='doctor'){txt=ic('doctor')+' '+Tr('اختر من تحميه');ok=p=>p.alive}
   else if(me.act==null&&me.role=='elder'){txt=ic('elder')+' '+Tr('اسأل: من تشك أنه مافيا؟');ok=p=>p.alive&&p.id!=me.id}
   else txt=ic('moon')+' '+Tr(me.act==null?'حلّ الليل... الكل ينام':'تم اختيارك... بانتظار الآخرين')}
  else{txt=ic('vote')+' '+Tr('صوّت على من تشك فيه');ok=p=>p.alive&&p.id!=me.id}}
 const sg=JSON.stringify([r.players,R_.phase,me.act,me.vote,me.alive]);
 if(sg!=OL.sg){OL.sg=sg;$('#grid').innerHTML=r.players.map(p=>`<div class="t ${p.alive?'':'dead'} ${p.id==me.id?'me':''} ${me.vote==p.id&&!night?'ch':''} ${ok(p)?'sel':''}" data-id="${p.id}">${p.av?avatar(p.av):''}<b>${esc(p.name)}</b>${me.mates.includes(p.id)?`<i class="mk">${ic('mafia')}</i>`:''}${me.chk[p.id]!==undefined?`<i class="ck">${ic(me.chk[p.id]?'warn':'check')}</i>`:''}<i class="cnt ${p.v?'on':''}">${p.v||''}</i></div>`).join('')}
 if(Date.now()>OL.hold)say(txt);
 document.querySelectorAll('#grid .t.sel').forEach(el=>el.onclick=async()=>{const x=await api('act',{code:OL.code,t:+el.dataset.id});if(x.err)return;if(x.res){sfx.reveal();await ov(`<div class="card c1"><div class="ic">${ic(x.res.m?'warn':'check')}</div><div class="nm" style="font-size:34px">${esc(x.res.name)}<br>${Tr(x.res.m?'مافيا!':'ليس مافيا')}</div></div>`,'تمام')}poll()});
 if(R_.status=='end'&&!OL.fin){OL.fin=1;sfx.start();const w=R_.winner;
  await ov(`<h1 style="font-size:36px;text-align:center">${ic(w=='mafia'?'mafia':'trophy')} ${Tr(w=='mafia'?'فازت المافيا!':'فاز المواطنون!')}</h1><div style="font-size:19px;text-align:center;line-height:1.9">${r.players.map(p=>`${esc(p.name)}: ${ic(R[p.role].i)} ${Tr(R[p.role].n)}`).join('<br>')}</div>`,'العودة للغرفة');OL.lg='';show('olobby');fabUp();lobbyUI(r)}}
async function showEv(r){const e=r.room.ev;OL.hold=Date.now()+4000;
 if(e.t=='n'){if(e.k=='kill'){sfx.kill();const el=document.querySelector(`#grid .t[data-id="${e.pid}"]`);if(el)el.classList.add('kill');say(ic('knife')+' '+Tr('المافيا قتلت {n}!').replace('{n}',esc(e.name)))}else{sfx.save();say(ic('doctor')+' '+Tr('الدكتور أنقذ الضحية! لم يمت أحد الليلة'))}}
 else if(e.k=='tie')say(ic('scale')+' '+Tr('تعادل في الأصوات! لم يخرج أحد'));
 else{sfx.reveal();await ov(e.role=='mafia'?`<h2>${Tr('{n} كان…').replace('{n}',esc(e.name))}</h2>`+card('mafia',r.room.ed):`<h2>${esc(e.name)}</h2><div style="font-size:22px">${Tr('خرج من اللعبة')}</div>`,'التالي')}}
/* بدء التشغيل */
(async()=>{applyST();if(window.FS_OFF){document.querySelector('[data-m=online]').style.display='none';$('#bDl').style.display='none';return}const h=await api('hello',{});if(h&&h.uid){UK=h.uid;localStorage.fsU=UK;if(h.settings&&!localStorage.fsS){Object.assign(ST,h.settings);applyST()}}
 const rm=(new URLSearchParams(location.search).get('room')||'').toUpperCase().slice(0,5),sv=localStorage.fsR;
 if(rm){MODE='online';await openOnl(rm)}
 else if(sv&&h&&h.uid){const r=await api('room_state',{code:sv,after:0});if(!r.err){MODE='online';enterRoom(sv)}else localStorage.removeItem('fsR')}})();

document.body.classList.remove('night');
show('intro');
applyST();
</script>
</body>
</html>
